nav > button:hover, nav > button.selected { color: #234e45; background: #dfe7e1; }
nav > button.selected { font-weight: 600; }
nav button em { margin-left: auto; font-style: normal; color: #919994; font-size: 11px; }
nav button i { width: 8px; height: 8px; border-radius: 50%; margin: 0 5px; }
.collections-head { display: flex; justify-content: space-between; align-items: center; margin-top: 24px; }
.collections-head .nav-label { margin-bottom: 8px; }
.collections-head button { border: 0; background: transparent; color: #77807b; padding: 2px 10px; }
.sidebar-bottom { margin-top: auto; }
.sidebar-bottom > button { margin-bottom: 14px; }
.profile { border-top: 1px solid #dbe0da; display: flex; align-items: center; gap: 9px; padding: 16px 6px 0; color: #606863; }
.profile > span { background: #d4ddd6; width: 31px; height: 31px; border-radius: 50%; display:grid; place-items:center; font-size: 10px; font-weight:700; color:#315f55; }
.profile div { display:flex; flex-direction:column; flex: 1; }
.profile strong { font-size: 11px; font-weight:600; color:#333936; }
.profile small { font-size: 10px; color:#8b938e; margin-top:2px; }
main { grid-column: 2; min-width: 0; }
header { height: 78px; padding: 0 42px; display:flex; align-items:center; gap: 12px; border-bottom: 1px solid #e7e7e2; background: rgba(250,250,247,.88); backdrop-filter: blur(12px); position:sticky; top:0; z-index:2; }
.searchbox { height: 39px; flex: 1; max-width: 460px; display:flex; align-items:center; gap:10px; color:#8c938f; background:#fff; border:1px solid #dedfda; border-radius:9px; padding:0 11px; box-shadow: 0 1px 2px #27352e08; }
.searchbox:focus-within { border-color:#78988f; box-shadow:0 0 0 3px #315f5512; }
.searchbox input { border:0; outline:0; flex:1; min-width:0; background:transparent; color:#313633; font-size:13px; }
.searchbox input::placeholder { color:#9ba19d; }
kbd { border:1px solid #e0e1dd; border-radius:5px; background:#f7f7f4; color:#8f9692; padding:2px 6px; font: 10px 'DM Sans'; box-shadow: 0 1px 0 #ddd; }
.add-button { margin-left:auto; height:39px; border:0; background:#315f55; color:#fff; border-radius:8px; padding:0 15px; display:flex; align-items:center; gap:8px; font-size:12px; font-weight:600; box-shadow:0 3px 9px #315f5526; }
.add-button:hover { background:#264f46; transform:translateY(-1px); }
.avatar { width:37px; height:37px; border:1px solid #d6dbd5; border-radius:50%; background:#e6ebe6; color:#315f55; font-size:10px; font-weight:700; }
.content { max-width: 1110px; margin: 0 auto; padding: 49px 50px 80px; }
.title-row { display:flex; justify-content:space-between; align-items:flex-end; margin-bottom:28px; }
