.bookmarks { border-top:1px solid #e0e1dc; }
.bookmark-card { position:relative; display:grid; grid-template-columns:42px minmax(0,1fr) 70px; gap:16px; padding:20px 8px 20px 3px; border-bottom:1px solid #e3e4df; align-items:start; transition:.18s ease; }
