.bookmark-card:hover .bookmark-title svg { opacity:1; transform:none; }
.bookmark-body > p { margin:6px 0 10px; color:#747b77; font-size:11.5px; line-height:1.45; max-width:690px; white-space:nowrap; text-overflow:ellipsis; overflow:hidden; }
.meta { display:flex; align-items:center; gap:7px; color:#999f9b; font-size:10px; }
.meta b { font-weight:400; color:#c1c4c1; }
.meta small { background:#eef0ec; color:#6f7772; padding:3px 7px; border-radius:4px; font-size:9px; }
