.actions button.is-favorite { color:#d4972f; opacity:1; }
.item-menu { position:absolute; top:34px; right:0; background:#fff; padding:5px; border:1px solid #dedfda; border-radius:8px; box-shadow:0 12px 30px #27352e24; width:145px; z-index:4; }
.item-menu button { width:100%; border:0; background:transparent; color:#a4473b; display:flex; align-items:center; gap:8px; padding:8px; font-size:11px; border-radius:5px; }
.item-menu button:hover { background:#fbefed; }
.bookmarks.grid { border:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.bookmarks.grid .bookmark-card { grid-template-columns:42px 1fr 60px; border:1px solid #e2e3de; background:#fff; border-radius:11px; padding:18px; min-height:150px; }
.bookmarks.grid .bookmark-card:hover { margin:0; box-shadow:0 10px 30px #28382f12; transform:translateY(-2px); }
.bookmarks.grid .bookmark-body > p { white-space:normal; height:34px; }
.bookmarks.grid .meta { flex-wrap:wrap; }
.bookmarks.grid .actions { opacity:.6; }
.empty { margin-top:70px; text-align:center; color:#8a928e; }
.empty svg { color:#315f55; background:#e3eae5; padding:12px; width:52px; height:52px; border-radius:50%; }
.empty h2 { font:600 17px 'Manrope'; color:#39413d; margin:16px 0 5px; }
.empty p { font-size:12px; }
.empty button { border:0; border-radius:7px; background:#315f55; color:white; padding:9px 13px; font-size:11px; margin-top:8px; }
.modal-backdrop { position:fixed; inset:0; z-index:10; background:#18211d80; backdrop-filter:blur(3px); display:grid; place-items:center; padding:20px; }
.modal { width:min(460px,100%); border-radius:14px; background:#fbfbf8; padding:26px; box-shadow:0 24px 80px #1e2823aa; animation:pop .2s ease-out; }
@keyframes pop { from { opacity:0; transform:translateY(8px) scale(.985); } }
.modal-head { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:24px; }
.modal-head h2 { margin:0; font:600 22px 'Manrope'; letter-spacing:-.5px; }
.modal-head button { margin-top:-5px; }
.modal label { display:block; color:#525a56; font-size:11px; font-weight:600; margin-top:15px; }
.modal label > span { float:right; color:#a1a6a3; font-weight:400; }
.modal input, .modal select { display:block; width:100%; height:42px; margin-top:7px; border:1px solid #d9dcd7; border-radius:8px; background:white; padding:0 12px; outline:none; color:#2d3430; font-size:12px; }
.modal input:focus, .modal select:focus { border-color:#70958b; box-shadow:0 0 0 3px #315f5512; }
.select-field { position:relative; }
.select-field select { appearance:none; }
.select-field svg { position:absolute; right:12px; top:20px; color:#8a918d; pointer-events:none; }
.modal-actions { display:flex; justify-content:flex-end; gap:8px; margin-top:25px; padding-top:19px; border-top:1px solid #e5e6e2; }
