@media (max-width: 760px) {
  .app { display:block; }
  aside { position:static; width:auto; height:auto; padding:16px; }
  aside nav, .sidebar-bottom { display:none; }
  .brand { padding:0; }
  main { width:100%; }
  header { padding:12px 18px; height:auto; flex-wrap:wrap; }
  .searchbox { order:2; max-width:none; flex-basis:100%; }
  .add-button { margin-left:auto; }
  .content { padding:32px 20px 60px; }
  .title-row { align-items:flex-start; gap:20px; }
  .tools .sort-wrap { display:none; }
  .bookmarks.grid { grid-template-columns:1fr; }
  .bookmark-card { grid-template-columns:38px minmax(0,1fr) 30px; gap:12px; }
  .bookmark-body > p { white-space:normal; }
  .actions > button:first-child { display:none; }
}

