import { chromium } from '@playwright/test';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(`console ${m.type()}: ${m.text()}`); });
page.on('pageerror', e => errors.push(`pageerror: ${e}`));
await page.goto('http://127.0.0.1:4000', { waitUntil: 'networkidle' });
await page.waitForSelector('[data-harness-ready="true"]');
if (await page.locator('.bookmark-card').count() < 7) throw new Error('Expected bookmark cards');
await page.getByPlaceholder('Search your bookmarks...').fill('Linear');
if (await page.locator('.bookmark-card').count() !== 1) throw new Error('Search failed');
await page.getByPlaceholder('Search your bookmarks...').fill('');
await page.getByRole('button', { name: 'Add bookmark', exact: true }).click();
await page.getByLabel('URL').fill('https://example.com/article');
await page.locator('label').filter({ hasText: 'Title' }).locator('input').fill('Example article');
await page.getByRole('button', { name: 'Save bookmark' }).click();
await page.getByText('Example article').waitFor();
await page.screenshot({ path: '/work/.harness/bookmarks.png', fullPage: true });
console.log(JSON.stringify({ cards: await page.locator('.bookmark-card').count(), errors }));
await browser.close();
JS

