+  const [tags, setTags] = useState(item?.tags?.join(', ') || '');
+  const [fetching, setFetching] = useState(false);
+  const [enriched, setEnriched] = useState(false);
+
+  const enrich = () => {
+    if (isEdit || !url.trim() || enriched) return;
+    setFetching(true);
